#!/usr/bin/env python3
"""Compare shared chat prior/turn validation to both saved baseline implementations."""
import json, os, shutil, subprocess, tempfile
from pathlib import Path
ROOT=Path(__file__).resolve().parent.parent
BASELINE = 'flow baseline_legacy_prior(prior: Previous) -> string {\n    if prior.task == "" {\n        if prior.result != "" || prior.tool != "" || prior.outcome != "" || prior.answer != "" {\n            return "invalid empty prior selection";\n        }\n        return "";\n    }\n    if question_error(prior.task) != "" || !legacy_bounded(prior.result, 256) || !legacy_bounded(prior.answer, 512) {\n        return "invalid selected prior result";\n    }\n    if prior.tool == "" {\n        if prior.outcome != "" { return "prior outcome without tool"; }\n    } else if (prior.tool != "read" && prior.tool != "search") || !legacy_bounded(prior.outcome, 266) || !starts_with(prior.outcome, "complete: ") {\n        return "invalid selected prior tool";\n    }\n    return "";\n}\n\nflow baseline_unicode_prior(prior: Previous) -> string {\n    if prior.task == "" {\n        if prior.result != "" || prior.tool != "" || prior.outcome != "" || prior.answer != "" {\n            return "invalid empty prior selection";\n        }\n        return "";\n    }\n    if !unicode_bounded(prior.task, 512) || !unicode_bounded(prior.result, 256) || !unicode_bounded(prior.answer, 512) {\n        return "invalid selected prior result";\n    }\n    if prior.tool == "" {\n        if prior.outcome != "" { return "prior outcome without tool"; }\n    } else if (prior.tool != "read" && prior.tool != "search") || !unicode_bounded(prior.outcome, 262154) || !(starts_with(prior.outcome, "complete: ") || (prior.tool == "search" && starts_with(prior.outcome, "incomplete: "))) {\n        return "invalid selected prior tool";\n    }\n    return "";\n}\n\nflow baseline_turn(invocation: Invocation) -> string {\n    let invalid = admission_error(invocation.usage, invocation.maximum); if invalid != "" { return invalid; }\n    let selected = baseline_legacy_prior(invocation.prior); if selected != "" { return selected; }\n    let used = invocation.usage;\n    if invocation.admitted == 0 {\n        if invocation.prior.task != "" || used.steps != 0 || used.calls != 0 || used.tokens != 0 || used.tools != 0 || used.scan != 0 {\n            return "first turn must own an empty invocation";\n        }\n    } else if invocation.admitted == 1 {\n        let tools = if invocation.prior.tool == "" { 0 } else { 1 };\n        if invocation.prior.task == "" || used.steps != 5 + tools * 2 || used.calls != 3 + tools ||\n            used.tokens != (3 + tools) * 2048 || used.tools != tools || (used.scan != tools * 4096 && used.scan != tools * 16384) {\n            return "prior selection and invocation ledger disagree";\n        }\n    } else { return "turn limit reached"; }\n    return "";\n}\n\nflow baseline_unicode_turn(invocation: Invocation) -> string {\n    let invalid = admission_error(invocation.usage, invocation.maximum); if invalid != "" { return invalid; }\n    let selected = baseline_unicode_prior(invocation.prior); if selected != "" { return selected; }\n    let used = invocation.usage;\n    if invocation.admitted == 0 {\n        if invocation.prior.task != "" || used.steps != 0 || used.calls != 0 || used.tokens != 0 || used.tools != 0 || used.scan != 0 {\n            return "first turn must own an empty invocation";\n        }\n    } else if invocation.admitted == 1 {\n        let tools = if invocation.prior.tool == "" { 0 } else { 1 };\n        if invocation.prior.task == "" || used.steps != 5 + tools * 2 || used.calls != 3 + tools ||\n            used.tokens != (3 + tools) * 2048 || used.tools != tools || (used.scan != tools * 4096 && used.scan != tools * 16384) {\n            return "prior selection and invocation ledger disagree";\n        }\n    } else { return "turn limit reached"; }\n    return "";\n}\n'

def main():
    values=['', 'task', ' ', '中文', '😀', 'x\ny', '\u202e', 'x'*129, 'x'*266, 'x'*512, 'x'*513, 'complete: good', 'incomplete: partial']
    base={'task':'task','result':'result','tool':'','outcome':'','answer':'answer'}
    items=[dict(task='',result='',tool='',outcome='',answer=''),base]
    for name in base:
        for value in values:
            item=dict(base);item[name]=value;items.append(item)
    for tool in ('read','search','bad'):
        for outcome in ('complete: good','incomplete: partial','bad'):
            items.append(dict(base,tool=tool,outcome=outcome))
    def lit(x):return json.dumps(x,ensure_ascii=False)
    expr=['Previous { '+', '.join(k+' = '+lit(v) for k,v in item.items())+' }' for item in items]
    with tempfile.TemporaryDirectory(prefix='nomo-chat-compat-') as directory:
        project=Path(directory)/'project';shutil.copytree(ROOT,project,ignore=shutil.ignore_patterns('.git','.etas','tmp','__pycache__'));(project/'.etas').mkdir()
        path=project/'src/nomo/main.es';source=path.read_text().replace('module nomo.main;', 'module nomo.main;\nimport std.text.starts_with;\nimport nomo.core.read_text.bounded as unicode_bounded;\nimport nomo.harness.harness_model_contract.bounded as legacy_bounded;\nimport nomo.model.model_tool_contract.question_error;\nimport nomo.harness.harness_tool_chat_contract.{Previous, Invocation, default_maximum, admission_error, fresh_invocation, prior_error as current_legacy_prior, turn_error as current_legacy_turn};\nimport nomo.harness.read_tool_chat_contract.{prior_error as current_unicode_prior, turn_error as current_unicode_turn};',1)
        source+='\n'+BASELINE+'\npublic flow chat_compat_probe(args: Array<string>) -> i32 {\n    let items: Array<Previous> = ['+',\n'.join(expr)+'];\n    for prior in items limit Iterations(100) {\n        if current_legacy_prior(prior) != baseline_legacy_prior(prior) || current_unicode_prior(prior) != baseline_unicode_prior(prior) { return 1; }\n        let fresh = fresh_invocation();\n        let first = Invocation { usage = fresh.usage, maximum = default_maximum(), admitted = 0, prior = prior };\n        if current_legacy_turn(first) != baseline_turn(first) || current_unicode_turn(first) != baseline_unicode_turn(first) { return 2; }\n        let second = Invocation { usage = fresh.usage, maximum = default_maximum(), admitted = 1, prior = prior };\n        if current_legacy_turn(second) != baseline_turn(second) || current_unicode_turn(second) != baseline_unicode_turn(second) { return 3; }\n    }\n    return 0;\n}\n'
        path.write_text(source);env=dict(os.environ,NOMO_ETAS_GRAPH='026-v68')
        command=['docker','compose','--env-file','/dev/null','-f','compose.yaml','-f','config/etas-026-official-compose.yaml','-f','config/etas-runtime-cache-compose.yaml','run','--rm','--no-deps','-T','dev','python3','-B','/workspace/scripts/nomo-verified-etas.py','run','/workspace','--flow','chat_compat_probe','--profile','foundation','--allow-effects']
        result=subprocess.run(command,cwd=project,env=env,text=True,capture_output=True,timeout=120)
        assert result.returncode==0 and '"value":"0"' in result.stdout.replace(' ',''),(result.stdout,result.stderr)
        print('PASS',len(items),'prior values and both first/second-turn validations against baseline')

if __name__=='__main__':main()
